"""Generated by make_c3_2.py for chart FIP (second-order parameter enclosure; see make_c3_2.py)."""
import math
import numpy as np
from numba import njit
from nbcoef_c3_FIP_2 import coef_val2, coef_abs2, DEG
ARC_PAD = 1e-12
PAIRS = np.array([[0, 0], [0, 1], [0, 2], [0, 3], [1, 1], [1, 2], [1, 3], [2, 2], [2, 3], [3, 3]])
TRIPLES = np.array([[a, b, c] for a in range(4) for b in range(a, 4) for c in range(b, 4)])
MULT3 = np.array([1.0 if (a == b and b == c) else (3.0 if (a == b or b == c) else 6.0) for a, b, c in TRIPLES])
@njit(cache=True)
def box_coeffs2(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi, x3lo, x3hi):
    lo = np.array([x0lo, x1lo, x2lo, x3lo]); hi = np.array([x0hi, x1hi, x2hi, x3hi])
    xc = 0.5 * (lo + hi)
    rr = 0.5 * (hi - lo) * (1 + 1e-12) + 1e-15 * (np.abs(xc) + 1.0)
    aa = np.abs(xc); ab = aa + rr
    val = np.zeros((15, DEG + 1)); a0 = np.zeros((35, DEG + 1)); a1 = np.zeros((35, DEG + 1))
    coef_val2(xc, val); coef_abs2(aa, a0); coef_abs2(ab, a1)
    cmid = val[0].copy()
    crad = 1e-13 * a0[0] + 1e-300
    cmax = a1[0] * (1 + 1e-12)
    dcen = val[1:5].copy()
    dwid = (a1[1:5] - a0[1:5]) * (1 + 1e-12) + 1e-13 * a1[1:5]
    hcen = val[5:15].copy()
    sr = rr[0] + rr[1] + rr[2] + rr[3]
    rem = np.empty(DEG + 1)
    for k in range(DEG + 1):
        t3 = 0.0
        for m in range(20):
            t3 += MULT3[m] * a1[15 + m, k] * rr[TRIPLES[m, 0]] * rr[TRIPLES[m, 1]] * rr[TRIPLES[m, 2]]
        s1 = a1[1, k] + a1[2, k] + a1[3, k] + a1[4, k]
        s2 = 0.0
        for m in range(10):
            s2 += a1[5 + m, k]
        rem[k] = (t3 / 6.0 + 1e-13 * s1 * sr + 1e-13 * s2 * sr * sr) * (1 + 1e-12)
    qw = np.empty(10)
    for m in range(10):
        a = PAIRS[m, 0]; b = PAIRS[m, 1]
        qw[m] = 0.5 * rr[a] * rr[a] if a == b else rr[a] * rr[b]
    return cmid, crad, dcen, dwid, cmax, rr, hcen, rem, qw
@njit(cache=True)
def ff(k, j):
    p = 1.0
    for i in range(j):
        p *= (k - i)
    return p
@njit(cache=True)
def point_enclosure2(cmid, crad, dcen, dwid, hcen, rem, qw, rr, y, J, mode):
    """vc[j] = G^(j)(y; x_c), rad[j] >= |G^(j)(y; x) - vc[j]| over the box, j = 0..J+1.  mode 0: min of the two
    bounds (certificates); 1: second-order only; 2: mean-value only (tests)."""
    ay = abs(y)
    vc = np.empty(J + 2); rad = np.empty(J + 2)
    for j in range(J + 2):
        s = 0.0; mag = 0.0; rd = 0.0; pabs = 0.0; rsum = 0.0
        g = np.zeros(4); w = np.zeros(4); H = np.zeros(10)
        for k in range(j, DEG + 1):
            f = ff(k, j)
            pw = y ** (k - j) * f
            apw = ay ** (k - j) * f
            s += cmid[k] * pw
            mag += abs(cmid[k]) * apw
            rd += crad[k] * apw
            for v in range(4):
                g[v] += dcen[v, k] * pw
                w[v] += dwid[v, k] * apw
                pabs += rr[v] * abs(dcen[v, k]) * apw
            for m in range(10):
                H[m] += hcen[m, k] * pw
                pabs += qw[m] * abs(hcen[m, k]) * apw
            rsum += rem[k] * apw
            pabs += rem[k] * apw
        first = 0.0; old = 0.0
        for v in range(4):
            first += rr[v] * abs(g[v])
            old += rr[v] * (abs(g[v]) + w[v])
        second = 0.0
        for m in range(10):
            second += qw[m] * abs(H[m])
        new = first + second + rsum + 1e-12 * pabs
        tot = rd + (min(old, new) if mode == 0 else (new if mode == 1 else old))
        tot = tot + 1e-12 * (mag + tot)
        vc[j] = s; rad[j] = tot
    return vc, rad
@njit(cache=True)
def root_signs2(cmid, crad, dcen, dwid, cmax, rr, hcen, rem, qw, um, hh, J):
    M = um.size
    sg = np.zeros((J + 1, M), dtype=np.int64)
    hop = np.ones(M, dtype=np.bool_)
    for i in range(M):
        y = um[i]; h = hh[i]; ay = abs(y)
        vc, rad = point_enclosure2(cmid, crad, dcen, dwid, hcen, rem, qw, rr, y, J, 0)
        for j in range(J + 1):
            if abs(vc[j]) > rad[j]:
                hop[i] = False
            B2 = 0.0
            for k in range(j + 2, DEG + 1):
                B2 += cmax[k] * ff(k, j + 2) * (ay + h) ** (k - j - 2)
            B2 *= 1 + 1e-12
            m1 = abs(vc[j + 1]) + rad[j + 1]
            tail = rad[j] + h * m1 + 0.5 * h * h * B2
            tail = tail + 1e-15 * (abs(vc[j]) + tail)
            lo = vc[j] - tail
            hi = vc[j] + tail
            if lo > 0:
                sg[j, i] = 1
            elif hi < 0:
                sg[j, i] = -1
    any_hopeless = False
    for i in range(M):
        if hop[i]:
            any_hopeless = True
    return sg, any_hopeless
@njit(cache=True)
def dp_linear(sg):
    J1, M = sg.shape
    dp = np.full(M + 1, 999.0)
    dp[0] = 0.0
    rs = np.zeros(J1, dtype=np.int64)
    for i in range(M):
        best = 999.0
        for j in range(J1):
            v = sg[j, i]
            if v == 0:
                continue
            if i == 0 or sg[j, i - 1] != v:
                rs[j] = i
            cand = dp[rs[j]] + j
            if cand < best:
                best = cand
        dp[i + 1] = best
    return dp[M]
@njit(cache=True)
def count(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi, x3lo, x3hi, rlo, rhi, J, M0, rounds, cap, target):
    cmid, crad, dcen, dwid, cmax, rr, hcen, rem, qw = box_coeffs2(x0lo, x0hi, x1lo, x1hi, x2lo, x2hi, x3lo, x3hi)
    left = rlo + np.arange(M0) * ((rhi - rlo) / M0)
    width = np.full(M0, (rhi - rlo) / M0)
    best = 999.0
    for rd in range(rounds + 1):
        sg, hopeless = root_signs2(cmid, crad, dcen, dwid, cmax, rr, hcen, rem, qw, left + width / 2,
                                   width / 2 + ARC_PAD, J)
        best = min(best, dp_linear(sg))      # every round's bound is valid; keep the smallest
        if best <= target:
            return True, best
        if rd == rounds or hopeless or left.size > cap:
            break
        nsel = 0
        for i in range(left.size):
            if sg[0, i] == 0:
                nsel += 1
        if nsel == 0:
            break
        nl = np.empty(left.size + nsel); nw = np.empty(left.size + nsel)
        m = 0
        for i in range(left.size):
            if sg[0, i] == 0:
                nl[m] = left[i]; nw[m] = width[i] / 2; m += 1
                nl[m] = left[i] + width[i] / 2; nw[m] = width[i] / 2; m += 1
            else:
                nl[m] = left[i]; nw[m] = width[i]; m += 1
        left = nl; width = nw
    return False, best
